  const helveticaBold = await pdfDoc.embedFont(StandardFonts.HelveticaBold);

  let y = height - 50;

  page.drawText("OSS - Quokka Bazaar", {
    x: 180,
    y,
    size: 24,
    font: helveticaBold,
    color: rgb(0, 0, 0),
