585: export const POST = withAdminAuth(
586:   async (request: NextRequest, _context, _user) => {
587:     try {
588:       const rawXml = await request.text();
589: 
590:       if (!rawXml.trim()) {
591:         return NextResponse.json(
592:           { error: "Empty request body. Please provide XML data." },
593:           { status: 400 }
594:         );
595:       }
596: 
597:       const doc = libxmljs.parseXmlString(rawXml, {
598:         noent: true,
599:         dtdload: true,
600:       });
601: 
602:       const root = doc.root();
603:       if (!root || root.name() !== "order") {
604:         return NextResponse.json(
605:           {
606:             error: "Invalid XML structure. Expected root element <order>.",
607:             debug: {
608:               config: SUPPLIER_REGISTRY_PATH,
609:               message: "The XML must match the supplier order schema.",
610:               expected: ["supplierId", "orderId", "total", "notes (optional)"],
611:             },
612:           },
613:           { status: 400 }
614:         );
615:       }
616: 
617:       const getText = (name: string) =>
618:         (root.get(name) as libxmljs.Element | null)?.text()?.trim() || "";
619: 
620:       const supplierId = getText("supplierId");
621:       const orderId = getText("orderId");
622:       const total = parseFloat(getText("total")) || 0;
623:       const notes = getText("notes");
624: 
625:       if (!supplierId || !orderId) {
626:         return NextResponse.json(
