778: const INTERNAL_MCP_URL =
779:   process.env.MCP_SERVER_URL || "http://localhost:3000/api/mcp";
780: 
781: const MAX_TOOL_CALLS = 5;
782: 
783: interface McpTool {
784:   name: string;
785:   description: string;
786:   inputSchema: Record<string, unknown>;
787: }
788: 
789: interface MistralToolCall {
790:   id: string;
791:   type: "function";
792:   function: {
793:     name: string;
794:     arguments: string;
795:   };
796: }
797: 
798: interface MistralMessage {
799:   role: string;
800:   content?: string | null;
801:   tool_calls?: MistralToolCall[];
802:   tool_call_id?: string;
803:   name?: string;
804: }
805: 
806: async function mcpRequest(
807:   serverUrl: string,
808:   method: string,
809:   params?: Record<string, unknown>,
810:   headers?: Record<string, string>
811: ) {
812:   const response = await fetch(serverUrl, {
813:     method: "POST",
814:     headers: {
815:       "Content-Type": "application/json",
816:       ...headers,
817:     },
818:     body: JSON.stringify({
819:       jsonrpc: "2.0",
820:       id: crypto.randomUUID(),
821:       method,
822:       params,
823:     }),
824:   });
825:   return response.json();
826: }
827: 
828: async function discoverTools(
829:   serverUrl: string,
830:   headers?: Record<string, string>
831: ): Promise<McpTool[]> {
832:   try {
833:     const response = await mcpRequest(
834:       serverUrl,
835:       "tools/list",
836:       undefined,
837:       headers
838:     );
839:     return response.result?.tools || [];
840:   } catch {
841:     return [];
842:   }
843: }
844: 
845: function mcpToolsToMistralFormat(tools: McpTool[]) {
846:   return tools.map((tool) => ({
847:     type: "function" as const,
848:     function: {
849:       name: tool.name,
850:       description: tool.description,
851:       parameters: tool.inputSchema,
852:     },
853:   }));
854: }
855: 
856: async function callMcpTool(
857:   serverUrl: string,
858:   name: string,
859:   args: Record<string, unknown>,
860:   headers?: Record<string, string>
861: ): Promise<string> {
862:   const response = await mcpRequest(
863:     serverUrl,
864:     "tools/call",
865:     { name, arguments: args },
866:     headers
867:   );
868:   const content = response.result?.content;
869:   if (Array.isArray(content) && content.length > 0) {
870:     return content.map((c: { text?: string }) => c.text || "").join("\n");
871:   }
872:   return JSON.stringify(response.result || response.error || {});
873: }
874: 
875: async function callMistral(
876:   apiKey: string,
877:   messages: MistralMessage[],
878:   tools?: ReturnType<typeof mcpToolsToMistralFormat>
879: ) {
880:   const body: Record<string, unknown> = {
881:     model: "mistral-small-2603",
882:     messages,
883:     max_tokens: 1024,
884:     temperature: 0.7,
885:   };
886: 
887:   if (tools && tools.length > 0) {
888:     body.tools = tools;
889:     body.tool_choice = "auto";
890:   }
891: 
892:   const response = await fetch("https://api.mistral.ai/v1/chat/completions", {
893:     method: "POST",
894:     headers: {
895:       "Content-Type": "application/json",
896:       Authorization: `Bearer ${apiKey}`,
897:     },
898:     body: JSON.stringify(body),
899:   });
900: 
901:   return response;
902: }
