904: export async function POST(request: NextRequest) {
905:   try {
906:     const parsed = await parseBody(request, aiAssistantBodySchema);
907:     if (!parsed.success) return parsed.response;
908:     const { message, apiKey, mcpServerUrl } = parsed.data;
909: 
910:     if (containsBlockedPattern(message)) {
911:       return NextResponse.json(
