913:           response:
914:             "I'm sorry, but I can't process that request. I'm here to help with Quokka Bazaar products and services. How can I assist you today?",
915:         },
916:         { status: 200 }
917:       );
918:     }
919: 
920:     const internalHeaders = { [MCP_SESSION_HEADER]: MCP_SESSION_VALUE };
921: 
922:     const internalTools = await discoverTools(
923:       INTERNAL_MCP_URL,
924:       internalHeaders
925:     );
926: 
927:     const toolSourceMap = new Map<
928:       string,
929:       { url: string; headers?: Record<string, string> }
930:     >();
931:     for (const tool of internalTools) {
932:       toolSourceMap.set(tool.name, {
933:         url: INTERNAL_MCP_URL,
934:         headers: internalHeaders,
935:       });
936:     }
937: 
938:     const allTools = [...internalTools];
939: 
940: 
941: 
942: 
943:     if (mcpServerUrl) {
944:       try {
945:         const externalTools = await discoverTools(mcpServerUrl);
946:         for (const tool of externalTools) {
947:           if (!toolSourceMap.has(tool.name)) {
948:             toolSourceMap.set(tool.name, { url: mcpServerUrl });
949:             allTools.push(tool);
950:           }
951:         }
952:       } catch {
953: 
954:       }
955:     }
956: 
957:     const mistralTools = mcpToolsToMistralFormat(allTools);
958: 
959:     const messages: MistralMessage[] = [
960:       { role: "system", content: SYSTEM_PROMPT },
961:       { role: "user", content: message },
962:     ];
963: 
964:     let response = await callMistral(apiKey, messages, mistralTools);
965: 
966:     if (!response.ok) {
967:       const errorData = await response.json().catch(() => ({}));
968: 
969:       if (response.status === 401) {
970:         return NextResponse.json(
971:           { error: "Invalid API key. Please check your Mistral API key." },
972:           { status: 401 }
973:         );
974:       }
975: 
976:       if (response.status === 429) {
977:         return NextResponse.json(
978:           { error: "Rate limit exceeded. Please try again later." },
979:           { status: 429 }
980:         );
981:       }
982: 
983:       return NextResponse.json(
984:         {
985:           error:
986:             errorData.message || "Failed to get response from AI assistant",
987:         },
988:         { status: response.status }
989:       );
990:     }
991: 
992:     let data = await response.json();
993:     let assistantMessage = data.choices?.[0]?.message;
994:     let toolCallCount = 0;
995: 
996:     while (
997:       assistantMessage?.tool_calls &&
998:       assistantMessage.tool_calls.length > 0 &&
999:       toolCallCount < MAX_TOOL_CALLS
1000:     ) {
1001:       messages.push({
1002:         role: "assistant",
1003:         content: assistantMessage.content || null,
1004:         tool_calls: assistantMessage.tool_calls,
1005:       });
1006: 
1007:       for (const toolCall of assistantMessage.tool_calls) {
1008:         const toolName = toolCall.function.name;
1009:         let toolArgs: Record<string, unknown>;
1010:         try {
1011:           toolArgs = JSON.parse(toolCall.function.arguments || "{}");
1012:         } catch {
1013:           toolArgs = {};
1014:         }
1015: 
1016:         const source = toolSourceMap.get(toolName);
1017: 
1018: 
1019: 
1020:         const toolResult = source
1021:           ? await callMcpTool(source.url, toolName, toolArgs, source.headers)
1022:           : `Unknown tool: ${toolName}`;
1023: 
1024:         messages.push({
1025:           role: "tool",
1026:           tool_call_id: toolCall.id,
1027:           name: toolName,
1028:           content: toolResult,
1029:         });
1030: 
1031:         toolCallCount++;
1032:       }
1033: 
1034:       response = await callMistral(apiKey, messages, mistralTools);
1035: 
